{
  "arguments": [
    {
      "claim": "The killings of the captured Croatian combatants constitute a war crime of wilful killing of persons who had laid down their arms, prohibited by Article 8(c)(vi) of the Rome Statute.",
      "reasoning": "The victims were members of the Croatian armed forces who had surrendered and were detained as prisoners of war in a hospital under ICRC protection. Article 8(c)(vi) expressly criminalises \"Killing or wounding a combatant who, having laid down his arms or having no longer means of defence, has surrendered at discretion;\". The factual record shows that after the surrender, the prisoners were removed from the protected hospital, handed over to irregular forces, and shot, fulfilling the element of wilful killing of surrendered combatants. Therefore the conduct falls squarely within the war‑crime definition of the Rome Statute.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "Killing or wounding a combatant who, having laid down his arms or having no longer means of defence, has surrendered at discretion;"
        }
      ]
    },
    {
      "claim": "The removal of the prisoners from Vukovar hospital violated the protection afforded to civilian hospitals under Article 19 of the Fourth Geneva Convention.",
      "reasoning": "Article 19 of the Fourth Geneva Convention provides that \"The protection to which civilian hospitals are entitled shall not cease unless they are used to commit, outside their humanitarian duties, acts harmful to the enemy.\" The hospital was a civilian medical facility under ICRC protection; it was not being used for hostile acts. By entering the hospital, seizing the patients, and transferring them to a location where they were subsequently killed, the JNA and its commander breached the unconditional protection guaranteed by the Convention.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "gc_iv",
          "article": "19",
          "quoted_text": "The protection to which civilian hospitals are entitled shall not cease unless they are used to commit, outside their humanitarian duties, acts harmful to the enemy."
        }
      ]
    },
    {
      "claim": "The commander of Operational Group South bears individual criminal responsibility under the doctrine of command responsibility because he had effective control over the forces that perpetrated the killings, knew or had reason to know of the crimes, and failed to take necessary measures to prevent them or punish the perpetrators.",
      "reasoning": "Customary international humanitarian law imposes liability on superiors who, exercising effective control over subordinates, either order, know about, or should have known about violations of the laws of armed conflict and do not take all feasible measures to prevent or repress such acts. The factual matrix demonstrates that the commander ordered the withdrawal of JNA military police, was informed by JNA officers of the abusive conduct of Territorial Defence and paramilitary forces, and nevertheless allowed the prisoners to fall into their hands, resulting in mass execution. This satisfies the three elements of command responsibility: (1) effective control, (2) knowledge (actual or constructive), and (3) failure to act.",
      "citations": []
    }
  ]
}

